begin;
create function pg_temp.assert_true(ok boolean,message text) returns text language plpgsql as $$begin if ok is distinct from true then raise exception 'ASSERTION FAILED: %',message;end if;return message;end$$;
create function pg_temp.expect_error(query text,code text) returns boolean language plpgsql as $$begin execute query;return false;exception when others then if sqlstate<>code then raise exception 'Expected %, got %: %',code,sqlstate,sqlerrm;end if;return true;end$$;
create temporary table execution_ids(key text primary key,id uuid not null);grant all on execution_ids to authenticated,service_role;
insert into private.role_permissions(role_id,permission_id) select r.id,p.id from private.roles r cross join private.permissions p where r.code='synthetic_personnel_resources' and p.code like 'fulfilment.%' on conflict do nothing;
insert into private.user_role_assignments(profile_id,role_id,scope) select 'c1000000-0000-0000-0000-000000000003',id,'global' from private.roles where code='synthetic_personnel_resources';
insert into private.role_permissions(role_id,permission_id) select r.id,p.id from private.roles r cross join private.permissions p where r.code='synthetic_provider_read_only' and p.code='fulfilment.read' on conflict do nothing;
insert into execution_ids select 'service',v.id from public.service_versions v join public.services s on s.id=v.service_id where s.code='home-cleaning';
insert into execution_ids select 'zone',id from public.service_zones where code='synthetic-personnel-zone';
insert into private.provider_requirement_sets(service_version_id,provider_type,zone_id,version,valid_from,requirements,capacity_unit,engagement_required,status,approved_by,approved_at,created_by)
 select service.id,'processing_partner',zone.id,1,now()-interval '1 day','[{"kind":"skill","code":"cleaning","scope":"worker","document_required":false}]','crew',false,'approved','d1000000-0000-0000-0000-000000000004',now(),'d1000000-0000-0000-0000-000000000003' from execution_ids service cross join execution_ids zone where service.key='service' and zone.key='zone';
insert into private.provider_capacity(provider_id,unit,units,created_by) values('d3000000-0000-0000-0000-000000000001','crew',2,'d1000000-0000-0000-0000-000000000003');
insert into private.provider_qualifications(provider_id,kind,code,subject_profile_id,valid_from,status,decided_by,decided_at,created_by) select 'd3000000-0000-0000-0000-000000000001','skill','cleaning',worker,now()-interval '1 day','approved','d1000000-0000-0000-0000-000000000004',now(),'d1000000-0000-0000-0000-000000000003' from unnest(array['d1000000-0000-0000-0000-000000000001'::uuid,'d1000000-0000-0000-0000-000000000002'::uuid]) worker;
insert into private.provider_coverage_areas(provider_id,service_version_id,zone_id,valid_from,created_by) select 'd3000000-0000-0000-0000-000000000001',s.id,z.id,now()-interval '1 day','d1000000-0000-0000-0000-000000000003' from execution_ids s cross join execution_ids z where s.key='service' and z.key='zone';
insert into private.provider_availability(provider_id,service_version_id,starts_at,ends_at,kind,created_by) select 'd3000000-0000-0000-0000-000000000001',id,now()-interval '1 day',now()+interval '3 days','working','d1000000-0000-0000-0000-000000000003' from execution_ids where key='service';
create function pg_temp.actor(n integer) returns void language plpgsql as $$begin perform set_config('request.jwt.claim.sub',case when n=1 then 'd1000000-0000-0000-0000-000000000001' when n=2 then 'd1000000-0000-0000-0000-000000000002' when n=3 then 'd1000000-0000-0000-0000-000000000003' when n=4 then 'd1000000-0000-0000-0000-000000000004' when n=5 then 'c1000000-0000-0000-0000-000000000003' when n=6 then 'a1000000-0000-0000-0000-000000000001' when n=7 then 'a1000000-0000-0000-0000-000000000002' when n=8 then 'e1000000-0000-0000-0000-000000000001' else 'c1000000-0000-0000-0000-000000000011' end,true);end$$;
create function pg_temp.fc(action text,data jsonb default '{}') returns uuid language plpgsql as $$declare work uuid;rev integer;taskrev integer;begin select id into work from execution_ids where key='work';rev=(public.read_work_order(work)->>'revision')::integer;if data->>'task_id' is not null then select (x->>'revision')::integer into taskrev from jsonb_array_elements(public.read_work_order(work)->'tasks') x where x->>'id'=data->>'task_id';end if;return public.fulfilment_command(work,action,data||jsonb_build_object('expected_revision',rev,'task_revision',taskrev,'reason','Synthetic execution test'),gen_random_uuid()::text);end$$;
create function pg_temp.qc(action text,data jsonb) returns uuid language plpgsql as $$declare work uuid;begin select id into work from execution_ids where key='work';return public.quality_command(work,action,data||jsonb_build_object('expected_revision',(public.read_work_order(work)->>'revision')::integer,'reason','Synthetic quality test'),gen_random_uuid()::text);end$$;
create function pg_temp.checklist(task uuid,phase text,actor integer) returns uuid language plpgsql as $$declare id uuid;begin perform pg_temp.actor(actor);id=pg_temp.fc('save_checklist',jsonb_build_object('task_id',task,'phase',phase,'answers','{"done":true}'::jsonb));perform pg_temp.fc('submit_checklist',jsonb_build_object('task_id',task,'id',id));return id;end$$;
grant execute on function pg_temp.assert_true(boolean,text),pg_temp.expect_error(text,text),pg_temp.actor(integer),pg_temp.fc(text,jsonb),pg_temp.qc(text,jsonb),pg_temp.checklist(uuid,text,integer) to authenticated,service_role;
set local role authenticated;select pg_temp.actor(3);
insert into execution_ids values('exec_template',public.fulfilment_configuration('prepare_checklist',jsonb_build_object('service_version_id',(select id from execution_ids where key='service'),'code','synthetic-execution','name','Synthetic execution','type','execution','version',1,'fields','[{"key":"done","label":"Work reviewed","type":"boolean","required":true}]'::jsonb),'synthetic-exec-template'));
insert into execution_ids values('qa_template',public.fulfilment_configuration('prepare_checklist',jsonb_build_object('service_version_id',(select id from execution_ids where key='service'),'code','synthetic-quality','name','Synthetic quality','type','quality','version',1,'fields','[{"key":"done","label":"Quality reviewed","type":"boolean","required":true}]'::jsonb),'synthetic-qa-template'));
select pg_temp.assert_true(pg_temp.expect_error($q$select public.fulfilment_configuration('publish_checklist',jsonb_build_object('id',(select id from execution_ids where key='exec_template')),'synthetic-self-publish')$q$,'42501'),'Checklist maker cannot publish own version');
select pg_temp.actor(4);select public.fulfilment_configuration('publish_checklist',jsonb_build_object('id',(select id from execution_ids where key='exec_template')),'synthetic-exec-publish');select public.fulfilment_configuration('publish_checklist',jsonb_build_object('id',(select id from execution_ids where key='qa_template')),'synthetic-qa-publish');
select pg_temp.actor(3);
insert into execution_ids values('policy',public.fulfilment_configuration('prepare_policy',jsonb_build_object('service_version_id',(select id from execution_ids where key='service'),'version',1,'valid_from',now()-interval '1 day','configuration',jsonb_build_object('transitions','[["awaiting_mobilisation","mobilising"],["mobilising","en_route"],["en_route","arrived"],["arrived","started"],["started","in_progress"],["in_progress","paused"],["paused","in_progress"],["in_progress","work_completed"]]'::jsonb,'evidence','["completion"]'::jsonb,'case_categories','["completion_dispute","damage","safety","delay"]'::jsonb,'pause_states','["paused"]'::jsonb,'execution_checklist',(select id from execution_ids where key='exec_template'),'quality_checklist',(select id from execution_ids where key='qa_template'),'handover_checklist',(select id from execution_ids where key='exec_template'),'allow_conditional_qa',false,'allow_partial_completion',false,'allow_closure_exception',true,'sla','{"mobilisation":600,"arrival":600,"start":600,"task_completion":3600,"quality_review":600,"rework":600,"case_acknowledgement":1,"case_resolution":1,"customer_response":600}'::jsonb)),'synthetic-fulfil-policy'));
select pg_temp.actor(4);select public.fulfilment_configuration('approve_policy',jsonb_build_object('id',(select id from execution_ids where key='policy')),'synthetic-fulfil-approve');
select pg_temp.actor(3);insert into execution_ids values('order_policy',public.order_policy_command('prepare',jsonb_build_object('service_version_id',(select id from execution_ids where key='service'),'version',1,'valid_from',now()-interval '1 day','payment_gate','no_upfront_payment','offer_seconds',600,'performance_weight','1','workload_weight','1'),'synthetic-clean-order-policy'));
select pg_temp.actor(4);select public.order_policy_command('approve',jsonb_build_object('id',(select id from execution_ids where key='order_policy')),'synthetic-clean-order-approve');
select pg_temp.actor(6);insert into execution_ids values('request',public.create_service_request('a2000000-0000-0000-0000-000000000001',(select id from execution_ids where key='service'),'e3000000-0000-0000-0000-000000000001','{"details":[{"bedrooms":1,"property":"flat"}]}','synthetic-fulfil-request'));
select public.change_service_request((select id from execution_ids where key='request'),1,'submit');select pg_temp.actor(3);select public.review_service_request((select id from execution_ids where key='request'),2);
insert into execution_ids values('quote',public.prepare_quotation((select id from execution_ids where key='request'),(select id from public.currencies where code='NGN'),now()+interval '1 day','Synthetic Home Cleaning scope','[{"description":"Home Cleaning synthetic job","kind":"labour","quantity":"1","unit_price":"100"}]','synthetic-fulfil-quote'));
select pg_temp.actor(4);select public.decide_quotation((select id from execution_ids where key='quote'),'approve');select pg_temp.actor(6);select public.decide_quotation((select id from execution_ids where key='quote'),'accept');
insert into execution_ids values('order',public.create_service_order((select id from execution_ids where key='quote'),jsonb_build_object('zone_id',(select id from execution_ids where key='zone'),'start',clock_timestamp()+interval '15 seconds','end',clock_timestamp()+interval '1 hour','reason','Synthetic cleaning order'),'synthetic-execution-order'));
select pg_temp.actor(4);select public.order_command((select id from execution_ids where key='order'),'release','{"expected_revision":1,"reason":"Synthetic release"}','synthetic-exec-release');
create temporary table candidate_payload(payload jsonb);grant all on candidate_payload to authenticated;
insert into candidate_payload select jsonb_agg(value->'id') from jsonb_array_elements(public.match_order((select id from execution_ids where key='order'),'[{"provider_id":"d3000000-0000-0000-0000-000000000001","worker_id":"d1000000-0000-0000-0000-000000000001","units":"1"},{"provider_id":"d3000000-0000-0000-0000-000000000001","worker_id":"d1000000-0000-0000-0000-000000000002","units":"1"}]'));
insert into execution_ids values('proposal',public.dispatch_command((select id from execution_ids where key='order'),'propose',jsonb_build_object('expected_revision',1,'candidates',(select payload from candidate_payload),'reason','Synthetic offer'),'synthetic-exec-proposal'));
reset role;insert into execution_ids select 'offer',id from private.assignment_offers where proposal_id=(select id from execution_ids where key='proposal');
insert into execution_ids select 'resource1',id from private.assignment_resources where offer_id=(select id from execution_ids where key='offer') and worker_id='d1000000-0000-0000-0000-000000000001';
insert into execution_ids select 'resource2',id from private.assignment_resources where offer_id=(select id from execution_ids where key='offer') and worker_id='d1000000-0000-0000-0000-000000000002';
set local role authenticated;select pg_temp.actor(8);select public.dispatch_command((select id from execution_ids where key='order'),'respond',jsonb_build_object('expected_revision',1,'offer_id',(select id from execution_ids where key='offer'),'accept',true,'reason','Synthetic accept'),'synthetic-exec-accept');select pg_temp.actor(3);select public.dispatch_command((select id from execution_ids where key='order'),'confirm',jsonb_build_object('expected_revision',1,'id',(select id from execution_ids where key='proposal'),'reason','Synthetic confirm'),'synthetic-exec-confirm');
insert into execution_ids values('work',public.create_work_order((select id from execution_ids where key='order'),jsonb_build_object('proposal_id',(select id from execution_ids where key='proposal'),'code','synthetic-cleaning','supervisor_id','d1000000-0000-0000-0000-000000000003','owner_id','d1000000-0000-0000-0000-000000000003','priority','normal','reason','Synthetic work creation'),'synthetic-work-create'));
select pg_temp.assert_true(public.create_work_order((select id from execution_ids where key='order'),jsonb_build_object('proposal_id',(select id from execution_ids where key='proposal'),'code','synthetic-cleaning','supervisor_id','d1000000-0000-0000-0000-000000000003','owner_id','d1000000-0000-0000-0000-000000000003','priority','normal','reason','Synthetic work creation'),'synthetic-work-create')=(select id from execution_ids where key='work'),'Work generation idempotent');
select pg_temp.assert_true(pg_temp.expect_error($q$select public.dispatch_command((select id from execution_ids where key='order'),'reassign','{"expected_revision":1,"reason":"Unsafe legacy release"}','synthetic-unsafe-release')$q$,'55000'),'Legacy dispatch cannot release capacity beneath active execution');
reset role;insert into execution_ids select 'start',id from private.work_orders where id=(select id from execution_ids where key='work');
set local role authenticated;select pg_temp.actor(3);
insert into execution_ids values('task1',pg_temp.fc('create_task',jsonb_build_object('resource_id',(select id from execution_ids where key='resource1'),'code','room-one','description','Synthetic Home Cleaning room one','start',public.read_work_order((select id from execution_ids where key='work'))->>'start','end',public.read_work_order((select id from execution_ids where key='work'))->>'end')));
insert into execution_ids values('task2',pg_temp.fc('create_task',jsonb_build_object('resource_id',(select id from execution_ids where key='resource2'),'code','room-two','description','Synthetic Home Cleaning room two','start',public.read_work_order((select id from execution_ids where key='work'))->>'start','end',public.read_work_order((select id from execution_ids where key='work'))->>'end')));
select pg_temp.assert_true(pg_temp.expect_error($q$select pg_temp.fc('close_work')$q$,'42501'),'Work cannot close while mandatory personnel tasks remain');
select pg_temp.actor(7);select pg_temp.assert_true(pg_temp.expect_error($q$select public.read_work_order((select id from execution_ids where key='work'))$q$,'42501'),'Unrelated customer cannot read work');
select pg_temp.actor(1);select pg_temp.assert_true(jsonb_array_length(public.read_work_order((select id from execution_ids where key='work'))->'tasks')=1,'Executing person sees only their own task');
select pg_temp.assert_true(pg_temp.expect_error($q$select pg_temp.fc('progress',jsonb_build_object('task_id',(select id from execution_ids where key='task2'),'state','started'))$q$,'42501'),'Personnel cannot advance another worker task');
select pg_sleep(15.2);
-- Each worker performs the approved operational path; completion remains separate from QA.
do $$declare n integer;task uuid;state text;begin for n in 1..2 loop select id into task from execution_ids where key='task'||n;perform pg_temp.actor(n);perform pg_temp.fc('accept_task',jsonb_build_object('task_id',task));
 foreach state in array array['mobilising','en_route','arrived'] loop perform pg_temp.fc('progress',jsonb_build_object('task_id',task,'state',state));end loop;
 perform pg_temp.fc('attendance',jsonb_build_object('task_id',task,'kind','check_in','latitude','6.500000','longitude','3.300000'));
 perform pg_temp.fc('progress',jsonb_build_object('task_id',task,'state','started'));perform pg_temp.fc('progress',jsonb_build_object('task_id',task,'state','in_progress'));
 perform pg_temp.checklist(task,'execution',n);perform pg_temp.fc('progress',jsonb_build_object('task_id',task,'state','work_completed'));
 end loop;end$$;
select pg_temp.actor(3);select pg_temp.assert_true(pg_temp.expect_error($q$select pg_temp.fc('supervisor_verify',jsonb_build_object('task_id',(select id from execution_ids where key='task1')))$q$,'23514'),'Incomplete mandatory evidence blocks supervision and QA release');
select pg_temp.actor(1);
insert into execution_ids values('evidence1',pg_temp.fc('prepare_upload',jsonb_build_object('task_id',(select id from execution_ids where key='task1'),'classification','completion','content_type','video/mp4','byte_size',1024)));
select pg_temp.assert_true(public.execution_document_reference((select id from execution_ids where key='evidence1'))->>'scan_status'='pending','Assigned worker receives a quarantined private video upload reference');
select pg_temp.actor(2);insert into execution_ids values('evidence2',pg_temp.fc('prepare_upload',jsonb_build_object('task_id',(select id from execution_ids where key='task2'),'classification','completion','content_type','image/jpeg','byte_size',1024)));
reset role;update private.document_objects set scan_status='clean' where id in(select document_id from private.execution_evidence where id in(select id from execution_ids where key in ('evidence1','evidence2')));
insert into execution_ids select 'submission1',id from private.execution_submissions where task_id=(select id from execution_ids where key='task1') and phase='execution';
insert into execution_ids select 'submission2',id from private.execution_submissions where task_id=(select id from execution_ids where key='task2') and phase='execution';
set local role authenticated;select pg_temp.actor(3);
do $$declare n integer;begin for n in 1..2 loop perform pg_temp.fc('review_evidence',jsonb_build_object('task_id',(select id from execution_ids where key='task'||n),'id',(select id from execution_ids where key='evidence'||n),'approve',true,'customer_visible',true));perform pg_temp.fc('review_checklist',jsonb_build_object('task_id',(select id from execution_ids where key='task'||n),'id',(select id from execution_ids where key='submission'||n),'approve',true));perform pg_temp.fc('supervisor_verify',jsonb_build_object('task_id',(select id from execution_ids where key='task'||n)));end loop;end$$;
insert into execution_ids values('qa1',pg_temp.qc('request',jsonb_build_object('task_id',(select id from execution_ids where key='task1'),'inspector_id','d1000000-0000-0000-0000-000000000004','scheduled_at',clock_timestamp())));
insert into execution_ids values('qa2',pg_temp.qc('request',jsonb_build_object('task_id',(select id from execution_ids where key='task2'),'inspector_id','d1000000-0000-0000-0000-000000000004','scheduled_at',clock_timestamp())));
insert into execution_ids values('quality1',pg_temp.checklist((select id from execution_ids where key='task1'),'quality',4));
select pg_temp.qc('submit',jsonb_build_object('id',(select id from execution_ids where key='qa1'),'submission_id',(select id from execution_ids where key='quality1'),'findings','[]'::jsonb));
select pg_temp.assert_true(pg_temp.expect_error($q$select pg_temp.qc('decide',jsonb_build_object('id',(select id from execution_ids where key='qa1'),'decision','approved'))$q$,'42501'),'Inspector cannot approve their own QA inspection');
select pg_temp.actor(5);select pg_temp.qc('decide',jsonb_build_object('id',(select id from execution_ids where key='qa1'),'decision','approved'));
select pg_temp.assert_true(pg_temp.expect_error($q$select pg_temp.fc('close_work')$q$,'42501'),'One completed worker cannot close a multi-person order');
insert into execution_ids values('quality2',pg_temp.checklist((select id from execution_ids where key='task2'),'quality',4));
select pg_temp.qc('submit',jsonb_build_object('id',(select id from execution_ids where key='qa2'),'submission_id',(select id from execution_ids where key='quality2'),'findings','[{"code":"missed-area","severity":"major","description":"Synthetic missed cleaning area","corrective_action":"Clean the missed area","blocking":true}]'::jsonb));
select pg_temp.actor(5);select pg_temp.qc('decide',jsonb_build_object('id',(select id from execution_ids where key='qa2'),'decision','rejected'));
select pg_temp.assert_true(public.read_work_order((select id from execution_ids where key='work'))->>'status'='rework_required','Failed QA produces an explicit retained rework lifecycle');
reset role;insert into execution_ids select 'rework_task',rework_task_id from private.rework_requests where original_task_id=(select id from execution_ids where key='task2');
select pg_temp.assert_true((select count(*)=1 from private.rework_requests where original_task_id=(select id from execution_ids where key='task2') and status='active'),'One active rework per unresolved defect');
select pg_temp.assert_true((select status='rejected' from private.quality_inspections where id=(select id from execution_ids where key='qa2')),'Original negative QA outcome preserved');
set local role authenticated;select pg_temp.actor(2);
select pg_temp.fc('accept_task',jsonb_build_object('task_id',(select id from execution_ids where key='rework_task')));
do $$declare task uuid;state text;begin select id into task from execution_ids where key='rework_task';foreach state in array array['mobilising','en_route','arrived'] loop perform pg_temp.fc('progress',jsonb_build_object('task_id',task,'state',state));end loop;perform pg_temp.fc('attendance',jsonb_build_object('task_id',task,'kind','check_in'));perform pg_temp.fc('progress',jsonb_build_object('task_id',task,'state','started'));perform pg_temp.fc('progress',jsonb_build_object('task_id',task,'state','in_progress'));perform pg_temp.checklist(task,'execution',2);perform pg_temp.fc('progress',jsonb_build_object('task_id',task,'state','work_completed'));end$$;
insert into execution_ids values('rework_evidence',pg_temp.fc('prepare_upload',jsonb_build_object('task_id',(select id from execution_ids where key='rework_task'),'classification','completion','content_type','image/jpeg','byte_size',512)));
reset role;update private.document_objects set scan_status='clean' where id=(select document_id from private.execution_evidence where id=(select id from execution_ids where key='rework_evidence'));
insert into execution_ids select 'rework_submission',id from private.execution_submissions where task_id=(select id from execution_ids where key='rework_task') and phase='execution';
set local role authenticated;select pg_temp.actor(3);select pg_temp.fc('review_evidence',jsonb_build_object('task_id',(select id from execution_ids where key='rework_task'),'id',(select id from execution_ids where key='rework_evidence'),'approve',true,'customer_visible',true));select pg_temp.fc('review_checklist',jsonb_build_object('task_id',(select id from execution_ids where key='rework_task'),'id',(select id from execution_ids where key='rework_submission'),'approve',true));select pg_temp.fc('supervisor_verify',jsonb_build_object('task_id',(select id from execution_ids where key='rework_task')));
insert into execution_ids values('qa_rework',pg_temp.qc('request',jsonb_build_object('task_id',(select id from execution_ids where key='rework_task'),'inspector_id','d1000000-0000-0000-0000-000000000004','scheduled_at',clock_timestamp())));
insert into execution_ids values('quality_rework',pg_temp.checklist((select id from execution_ids where key='rework_task'),'quality',4));select pg_temp.qc('submit',jsonb_build_object('id',(select id from execution_ids where key='qa_rework'),'submission_id',(select id from execution_ids where key='quality_rework'),'findings','[]'::jsonb));
select pg_temp.actor(5);select pg_temp.qc('decide',jsonb_build_object('id',(select id from execution_ids where key='qa_rework'),'decision','approved'));
select pg_temp.assert_true(public.read_work_order((select id from execution_ids where key='work'))->>'status'='awaiting_customer_confirmation','Independent reinspection enables customer confirmation');
reset role;select pg_temp.assert_true((select count(*)=1 from private.rework_requests where original_task_id=(select id from execution_ids where key='task2') and status='accepted'),'Rework acceptance preserves the defect relation');
set local role authenticated;
-- Handover is a separate versioned checklist and review for every delivered task.
do $$declare task uuid;submission uuid;begin for task in select id from execution_ids where key in ('task1','task2','rework_task') loop submission=pg_temp.checklist(task,'handover',3);perform pg_temp.actor(4);perform pg_temp.fc('review_checklist',jsonb_build_object('task_id',task,'id',submission,'approve',true));end loop;end$$;
select pg_temp.actor(6);select pg_temp.fc('customer_confirm','{"decision":"disputed","comment":"Synthetic customer completion dispute"}');
select pg_temp.assert_true(public.read_work_order((select id from execution_ids where key='work'))->>'status'='under_review','Customer sees safe progress without internal investigation state');
reset role;insert into execution_ids select 'dispute_case',id from private.service_cases where work_order_id=(select id from execution_ids where key='work') and category='completion_dispute';
set local role authenticated;select pg_temp.actor(5);select pg_temp.assert_true(pg_temp.expect_error($q$select pg_temp.fc('close_work')$q$,'42501'),'Customer dispute blocks administrative closure');
select pg_temp.actor(3);select public.execution_case_command((select id from execution_ids where key='order'),'propose_resolution',jsonb_build_object('id',(select id from execution_ids where key='dispute_case'),'expected_revision',1,'requirements','{"action":"Customer walkthrough completed"}'::jsonb,'reason','Synthetic resolution proposal'),'synthetic-dispute-proposal');
select pg_temp.assert_true(pg_temp.expect_error($q$select public.execution_case_command((select id from execution_ids where key='order'),'resolve',jsonb_build_object('id',(select id from execution_ids where key='dispute_case'),'expected_revision',2,'reason','Self resolution'),'synthetic-self-resolution')$q$,'42501'),'Resolution maker cannot approve their own proposal');
select pg_temp.actor(4);select public.execution_case_command((select id from execution_ids where key='order'),'resolve',jsonb_build_object('id',(select id from execution_ids where key='dispute_case'),'expected_revision',2,'reason','Synthetic independent resolution'),'synthetic-dispute-resolve');
select pg_temp.actor(6);select pg_temp.fc('customer_confirm','{"decision":"confirmed","comment":"Synthetic confirmation after resolution"}');
select pg_temp.assert_true(public.read_work_order((select id from execution_ids where key='work'))->>'status'='completed','Current corporate/individual approver acknowledgement is a separate completion event');
select pg_temp.fc('feedback','{"rating":4,"comment":"Synthetic first feedback"}');select pg_temp.fc('feedback','{"rating":5,"comment":"Synthetic revised feedback"}');
reset role;select pg_temp.assert_true((select count(*)=2 from public.customer_feedback where work_order_id=(select id from execution_ids where key='work')),'Feedback corrections retain both revisions');
select pg_temp.assert_true((select count(*)=2 from private.provider_capacity_reservations capacity join private.assignment_resources resource on resource.reservation_id=capacity.id join private.assignment_offers offer on offer.id=resource.offer_id where offer.proposal_id=(select id from execution_ids where key='proposal') and capacity.status='assigned'),'Capacity remains assigned through provider completion, QA and customer confirmation');
select pg_temp.assert_true((select status='completed' from private.service_orders where id=(select id from execution_ids where key='order')),'Final customer confirmation updates canonical order completion without releasing capacity');
set local role authenticated;select pg_temp.actor(5);select pg_temp.fc('close_work');
select pg_temp.assert_true(public.read_work_order((select id from execution_ids where key='work'))->>'status'='closed','Authorised closure completes the full assigned Home Cleaning workflow');
reset role;
select pg_temp.assert_true((select count(*)=0 from private.provider_capacity_reservations capacity join private.assignment_resources resource on resource.reservation_id=capacity.id join private.assignment_offers offer on offer.id=resource.offer_id where offer.proposal_id=(select id from execution_ids where key='proposal') and capacity.status='assigned'),'Capacity releases exactly at authorised final closure');
select pg_temp.assert_true((select status='closed' from private.service_orders where id=(select id from execution_ids where key='order')),'Order closure integrates with existing dispatch and commercial identity');
select pg_temp.assert_true((select count(*)=3 from private.provider_performance_events where metric='quality' and source_event_id in(select id from private.execution_history where work_order_id=(select id from execution_ids where key='work'))),'Three actual quality decisions produce three explainable observations');
select pg_temp.assert_true((select count(*)=1 from private.provider_performance_events where metric='completion' and source_event_id in(select id from private.execution_history where work_order_id=(select id from execution_ids where key='work'))),'Verified completion feeds exactly one provider observation');
set local role authenticated;select pg_temp.actor(1);select pg_temp.assert_true(pg_temp.expect_error($q$select public.execution_document_reference((select id from execution_ids where key='evidence1'))$q$,'42501'),'Former assigned worker loses sensitive evidence access after closure');
select pg_temp.actor(6);select pg_temp.assert_true(public.execution_document_reference((select id from execution_ids where key='evidence1'))->>'scan_status'='clean','Customer retains access only to reviewed customer-visible completion evidence');
reset role;
rollback;
